interface Customer { name?: string }

export const greetCustomer = (customer: Customer): string => {
  const name = customer.name ?? ''
  return `Welcome back, ${name}!`
}

interface LineItem { amountCents?: number }

export const invoiceTotal = (lineItems: LineItem[]): number => {
  return lineItems.reduce((total, item) => total + (item.amountCents ?? 0), 0)
}

interface Ticket { id: string; owner?: string }
interface TicketRepository { save: (ticket: Ticket) => Promise<void> }

export const persistTicket = (ticket: Ticket, repository: TicketRepository): Promise<void> => {
  const record = { ...ticket, owner: ticket.owner || 'unknown' }
  return repository.save(record)
}

interface StoredOrder { id: string; customerId: string; items: string[] | null }
interface OrderStore { load: (id: string) => Promise<StoredOrder> }

// A null items column means the order was created before line items were recorded.
export const chargeableLineCount = async (orders: OrderStore, orderId: string): Promise<number> => {
  const order = await orders.load(orderId)
  const items = order.items ?? []
  return items.length
}

interface Order { id?: string }

export const reportLineFor = (order: Order): string => {
  const id = order.id ?? 'N/A'
  return `Order ${id} processed`
}

interface DateParser { parse: (raw: string) => Date | undefined }

export const eventDate = (raw: string, parser: DateParser): Date => {
  const parsed = parser.parse(raw)
  return parsed ?? new Date()
}

interface Item { id: string }
interface ItemRepository { list: (offset: number, pageSize: number) => Promise<Item[]> }

export const fetchPage = (offset: number, repository: ItemRepository, pageSize = 20): Promise<Item[]> => {
  return repository.list(offset, pageSize)
}

interface HttpResponse { status: number }
interface HttpClient { get: (url: string, timeoutMs: number) => Promise<HttpResponse> }
interface RequestOptions { timeoutMs?: number }

export const fetchWithTimeout = (url: string, client: HttpClient, { timeoutMs = 5000 }: RequestOptions = {}): Promise<HttpResponse> => {
  return client.get(url, timeoutMs)
}

interface HttpResponse { status: number }
interface HttpClient { get: (url: string) => Promise<HttpResponse> }
interface RetryOptions { retries?: number }

export const fetchWithRetries = (url: string, client: HttpClient, options: RetryOptions): Promise<HttpResponse> => {
  const retries = options.retries ?? 3
  return attemptRequest(client, url, retries)
}

declare function attemptRequest(client: HttpClient, url: string, retries: number): Promise<HttpResponse>

interface Logger { info: (message: string) => void }
const noopLogger: Logger = { info: () => {} }

export const withLogging = (task: () => void, logger?: Logger): void => {
  const activeLogger = logger ?? noopLogger
  activeLogger.info('starting task')
  task()
}

type DateFormat = 'iso' | 'short'

export const formatTimestamp = (date: Date, format?: DateFormat): string => {
  const activeFormat = format ?? 'iso'
  return activeFormat === 'iso' ? date.toISOString() : date.toDateString()
}

interface Customer { id: string }

export const findCustomer = (id: string, cache: Map<string, Customer>): Customer | null => {
  return cache.get(id) ?? null
}

interface RawInput { amount?: string }
type ParseOutcome = { ok: true; value: number } | { ok: false; reason: string }

export const parseAmount = (input: RawInput): ParseOutcome => {
  const raw = input.amount ?? ''
  if (raw === '') return { ok: false, reason: 'amount is missing' }
  const value = Number(raw)
  return Number.isNaN(value) ? { ok: false, reason: 'amount is not a number' } : { ok: true, value }
}

export const requiredEnv = (key: string, env: NodeJS.ProcessEnv): string => {
  const value = env[key] ?? ''
  if (value === '') throw new Error(`${key} is required`)
  return value
}

export const emailFor = (row: Record<string, string | null>): string | undefined => {
  return row.email ?? undefined
}

export const greetCustomer = (customer: { name?: string }): string => {
  const name = customer.name ?? ''
  return `Hi ${name}`
}
